-- Home feed = every Vidu template fal.ai can run (146 after the safety list),
-- with Vidu's own demo clip and cover from platform.vidu.com/docs/templates
-- (linked from Vidu's CDN). Newest first: rows added later by sync-effects get a
-- later created_at and float to the top; this first batch is backdated.
--
-- Credits follow Vidu's per-template price: fal charges ≈ Vidu credits × $0.005
-- (40 → $0.20, 60 → $0.30, 100 → $0.50), × 1.25 margin / $0.01 per credit.
-- Left out on purpose: adult/suggestive, de-aging/child, violence, branded
-- characters and real people (see BLOCKED in _shared/effects.ts).

alter table public.effects
  add column if not exists width  integer,           -- demo clip size, so tiles keep its aspect ratio (no blurry crop)
  add column if not exists height integer;

create unique index if not exists effects_endpoint_value_idx on public.effects (endpoint, value);

-- Existing curated Vidu rows join the backdated first batch.
update public.effects set created_at = '2026-11-01' where endpoint = 'fal-ai/vidu/template-to-video';

insert into public.effects (id, endpoint, field, value, image_field, image_array, extra, title, subtitle, category, credits, preview_url, poster_url, width, height, sort, created_at)
select v.id, 'fal-ai/vidu/template-to-video', 'template', v.value, 'input_image_urls', true, '{"aspect_ratio":"9:16"}',
       v.title, v.subtitle, v.category, v.credits, v.preview, v.poster, v.w, v.h, v.sort, '2026-11-01'
